public class CityFinderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("full customer", "paris", CityFinder.cityOf(new Customer("Ann", new Address("PARIS"))));
        check("mixed-case city", "london", CityFinder.cityOf(new Customer("Dan", new Address("LoNdOn"))));
        check("already-lowercase city", "oslo", CityFinder.cityOf(new Customer("Eve", new Address("oslo"))));
        check("null address", "unknown", CityFinder.cityOf(new Customer("Bob", null)));
        check("null city inside address", "unknown", CityFinder.cityOf(new Customer("Cat", new Address(null))));
        check("null customer", "unknown", CityFinder.cityOf(null));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

